  height: 8px;
  background: rgba(255,255,255,0.25);
  border-radius: 4px;
  overflow: hidden;
}
.export-progress__bar {
  height: 100%;
  width: 0;
  background: var(--faktisk-blue);
  transition: width 0.3s;
}

/* Canvas */
.plugin-canvas {
  display: flex;
  flex-direction: column;
  gap: 12px;
  overflow: hidden;
  min-width: 0;
}

.canvas-area {
  position: relative;
  flex: 1;
  min-height: 200px;
  background: var(--bg-letterbox);
  border-radius: 10px;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}
.canvas-video {
  display: block;
  max-width: 100%;
  max-height: 100%;
  width: auto;
  height: auto;
  border-radius: 6px;
  background: #000;
}
.canvas-video:not([src]) { display: none; }
.canvas-empty {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px;
  text-align: center;
}
.canvas-empty p {
  max-width: 420px;
  font-size: 16px;
  color: #fff;
  margin: 0;
  line-height: 1.4;
}
.canvas-empty.hidden { display: none; }

/* Maske-overlegg — divs med backdrop-filter gir ekte blur-forhåndsvisning */
.mask-overlay {
  position: absolute;
  pointer-events: none; /* selve laget; maskene har pointer-events: auto */
}
.mask-box {
  position: absolute;
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 2px dashed rgba(255,255,255,0.85);
  border-radius: 4px;
  cursor: grab;
  pointer-events: auto;
  box-sizing: border-box;
}
.mask-box.selected { border-color: var(--faktisk-blue); border-style: solid; }
.mask-box.dragging { cursor: grabbing; }
.mask-box--ellipse {
  border-radius: 50%;
  /* Myk kant i forhåndsvisning — eksporten bruker radial alpha-fade i ffmpeg */
  -webkit-mask-image: radial-gradient(ellipse closest-side, #000 60%, transparent 100%);
  mask-image: radial-gradient(ellipse closest-side, #000 60%, transparent 100%);
}
.mask-box--ellipse.selected,
.mask-box--ellipse.inactive {
  /* Kantlinja må være synlig for å kunne treffe og dra masken */
  -webkit-mask-image: none;
  mask-image: none;
}
.mask-box.locked {
  /* Låst maske: klikk går rett gjennom til videoen */
  pointer-events: none;
  border-style: solid;
  border-color: rgba(255,255,255,0.45);
  cursor: default;
}

.mask-row__lock {
  background: transparent;
  font-size: 13px;
  cursor: pointer;
  padding: 0 2px;
  opacity: 0.6;
}
.mask-row__lock:hover { opacity: 1; }
.mask-row__lock.on { opacity: 1; }
.mask-row__bottom.islocked { opacity: 0.5; }
.mask-row__bottom select:disabled,
.mask-row__kf:disabled,
.mask-row__del:disabled { cursor: not-allowed; opacity: 0.5; }
.mask-box.inactive { opacity: 0.35; border-style: dotted; backdrop-filter: none; -webkit-backdrop-filter: none; }
.mask-box__label {
  position: absolute;
  top: -22px;
  left: 0;
  background: rgba(0,0,0,0.7);
  color: #fff;
  font-family: var(--font-bold);
  font-weight: bold;
  font-size: 11px;
  padding: 2px 7px;
  border-radius: 4px;
  white-space: nowrap;
}
.mask-box__resize {
  position: absolute;
  right: -7px;
  bottom: -7px;
  width: 14px;
  height: 14px;
  background: #fff;
  border: 2px solid var(--faktisk-blue);
  border-radius: 50%;
  cursor: nwse-resize;
}

/* Tidslinje. Feltet skal aldri spise videoen: det tar maks ~45 % av høyden,
   og med mange masker skroller lane-lista i stedet for å skvise resten. */
.timeline-stack {
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex-shrink: 0;
  padding: 0 16px;
  max-height: 45%;
  min-height: 0;
}
.timeline-row {
  display: grid;
  grid-template-columns: 90px 1fr;
  align-items: center;
  gap: 12px;
}
.timeline-row__label {
  font-family: var(--font-bold);
  font-weight: bold;
  font-size: 12px;
  color: #fff;
  opacity: 0.8;
}
.tl-toolbar {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 0 0 6px 102px;
}
.tl-btn {
  background: rgba(255,255,255,0.15);
  color: #fff;
  border-radius: 4px;
  font-family: var(--font-bold);
  font-weight: bold;
  font-size: 11px;
  padding: 2px 9px;
  cursor: pointer;
}
.tl-btn:hover { background: rgba(255,255,255,0.3); }
.tl-range {
  font-family: var(--font-bold);
  font-weight: bold;
  font-size: 11px;
  color: #fff;
  opacity: 0.75;
  font-variant-numeric: tabular-nums;
  margin-left: 6px;
}
.tl-hint {
  font-size: 10.5px;
  color: #fff;
  opacity: 0.45;
  margin-left: auto;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
@media (max-width: 1050px) {
  .tl-hint { display: none; }   /* hintet skal ikke presse tidslinjen på smale vinduer */
}

.tl-wrap {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-height: 0;
  overflow-y: auto;   /* skroller bare når timeline-stackens 45 %-tak er nådd */
  scrollbar-width: thin;
}
.timeline__track {
  position: relative;
  height: 16px;
  background: #6F6F6F;
  border-radius: 4px;
  cursor: pointer;
}
.tl-ruler { height: 16px; }
.tl-trim { height: 12px; background: #4A4A4A; cursor: default; overflow: visible; }
.tl-trim__sel {
  position: absolute;
  top: 0; bottom: 0;
  background: rgba(0, 80, 252, 0.45);
  border-top: 1px solid var(--faktisk-blue);
  border-bottom: 1px solid var(--faktisk-blue);
  pointer-events: none;
}
.tl-trim__handle {
  position: absolute;
  top: -4px; bottom: -4px;
  width: 10px;
  background: var(--faktisk-blue);
  border: 2px solid #fff;
  border-radius: 4px;
  cursor: ew-resize;
  transform: translateX(-50%);
  z-index: 4;
  box-shadow: 0 2px 6px rgba(0,0,0,0.35);
}
.tl-trim__handle:hover { background: var(--faktisk-blue-hover); }

.export-trim {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  font-family: var(--font-bold);
  font-weight: bold;
  font-size: 12px;
  color: #fff;
  opacity: 0.9;
}
#laneList { display: flex; flex-direction: column; gap: 6px; }
.lane .timeline__track { height: 13px; background: #5A5A5A; }
.lane .timeline-row__label {
  font-size: 11px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  cursor: pointer;
}
.lane.selected .timeline-row__label { opacity: 1; }

/* Playhead-kolonnen ligger over spor-kolonnen (90px label + 12px gap) */
.tl-headcol {
  position: absolute;
  left: 102px;
  right: 0;
  top: 0;
  bottom: 0;
  pointer-events: none;
}

.timeline__labels {
  display: flex;
  justify-content: space-between;
  margin-top: 6px;
  font-family: var(--font-bold);
  font-weight: bold;
  font-size: 11px;
  color: #fff;
  opacity: 0.85;
}
.hint-inline { opacity: 0.55; font-weight: normal; }

.ms-span {
  position: absolute;
  top: 2px;
  bottom: 2px;
  border-radius: 3px;
  opacity: 0.65;
  pointer-events: none;
}
.ms-span.selected { opacity: 1; }
.ms-kf {
  position: absolute;
  top: 50%;
  width: 7px;
  height: 7px;
  background: #fff;
  border-radius: 50%;
  transform: translate(-50%, -50%);
  pointer-events: none;
  box-shadow: 0 0 3px rgba(0,0,0,0.6);
}
.ms-head {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 2px;
  background: #fff;
  transform: translateX(-50%);
  pointer-events: none;
  z-index: 3;
  box-shadow: 0 0 4px rgba(0,0,0,0.5);
}
